/**
 * Catalog layout shared by the i18n scripts (languages design §3.2, §3.7).
 *
 * - `locales/en/<ns>.json`: generated by `extract.ts`, checked in. A flat
 *   map of key → English (ICU MessageFormat 1 subset).
 * - `locales/en/<ns>.notes.json`: translator notes from `// i18n: …`
 *   comments. Never shipped to the browser.
 * - `locales/<locale>/<ns>.json`: translations, key → `{ text, src }`,
 *   where `src` is the hash of the English the text was made from.
 * - `locales/pseudo/`: `en-XA` and `ar-XB`, built by `pseudo.ts`, ignored
 *   by git.
 *
 * A key's namespace is its first dotted segment (`library.trash.empty` →
 * `library`), so the key alone says which lazy chunk loads it. Two
 * namespaces are written for the registry render boundary: `action.<id>.*`
 * keys go to `actions`, and `reason:<English>` keys to `reasons`.
 */
import { createHash } from "node:crypto";
import { existsSync, readdirSync, readFileSync } from "node:fs";
import { join } from "node:path";

/** One namespace per chunk that renders messages (§3.7). */
export const MESSAGE_NAMESPACES = [
  "core",
  "menus",
  "slash",
  "palette",
  "colour",
  "insert",
  "outline",
  "tabs",
  "library",
  "settings",
  "comments",
  "sharing",
  "find",
  "print",
  "pwa",
  "consent",
  "desktop",
  "site",
] as const;
export const NAMESPACES = [
  ...MESSAGE_NAMESPACES,
  "actions",
  "reasons",
] as const;
export type Namespace = (typeof NAMESPACES)[number];

const MESSAGE_NAMESPACE_SET = new Set<string>(MESSAGE_NAMESPACES);
const NAMESPACE_SET = new Set<string>(NAMESPACES);

export const isNamespace = (name: string): name is Namespace =>
  NAMESPACE_SET.has(name);

/** The namespace a key belongs to, or null when its prefix names none. */
export function namespaceOf(key: string): Namespace | null {
  if (key.startsWith("action.")) return "actions";
  if (key.startsWith("reason:")) return "reasons";
  const first = key.split(".")[0];
  return key.includes(".") && MESSAGE_NAMESPACE_SET.has(first)
    ? (first as Namespace)
    : null;
}

export const LOCALES_DIR = "locales";
export const SOURCE_LOCALE_DIR = "en";
export const PSEUDO_DIR = "pseudo";
export const NOTES_SUFFIX = ".notes.json";

export type SourceCatalog = Record<string, string>;
export interface TranslatedEntry {
  text: string;
  src: string;
}
export type TranslatedCatalog = Record<string, TranslatedEntry>;

/** Hash of an English message; a translation made from other English is stale. */
export const sourceHash = (english: string): string =>
  createHash("sha1").update(english).digest("hex").slice(0, 8);

/** Stable JSON: keys sorted, two-space indent, trailing newline. */
export function serializeCatalog(catalog: Record<string, unknown>): string {
  const sorted = Object.fromEntries(
    Object.keys(catalog)
      .sort()
      .map((key) => [key, catalog[key]]),
  );
  return `${JSON.stringify(sorted, null, 2)}\n`;
}

/** Locale directories under `locales/` (not `pseudo/`). */
export function localeDirs(root: string): string[] {
  const dir = join(root, LOCALES_DIR);
  if (!existsSync(dir)) return [];
  return readdirSync(dir, { withFileTypes: true })
    .filter((entry) => entry.isDirectory() && entry.name !== PSEUDO_DIR)
    .map((entry) => entry.name)
    .sort();
}

/** `<ns>.json` files of one locale, parsed (notes files excluded). */
export function readLocale(
  root: string,
  locale: string,
): Map<string, Record<string, unknown>> {
  const dir = join(root, LOCALES_DIR, locale);
  const out = new Map<string, Record<string, unknown>>();
  if (!existsSync(dir)) return out;
  for (const name of readdirSync(dir).sort()) {
    if (!name.endsWith(".json") || name.endsWith(NOTES_SUFFIX)) continue;
    out.set(
      name.slice(0, -".json".length),
      JSON.parse(readFileSync(join(dir, name), "utf8")),
    );
  }
  return out;
}

/** `<ns>.notes.json` files of the English source, parsed. */
export function readNotes(root: string): Map<string, Record<string, string>> {
  const dir = join(root, LOCALES_DIR, SOURCE_LOCALE_DIR);
  const out = new Map<string, Record<string, string>>();
  if (!existsSync(dir)) return out;
  for (const name of readdirSync(dir).sort()) {
    if (!name.endsWith(NOTES_SUFFIX)) continue;
    out.set(
      name.slice(0, -NOTES_SUFFIX.length),
      JSON.parse(readFileSync(join(dir, name), "utf8")),
    );
  }
  return out;
}
